function userTbl(U){ return `<div class="tbl-w"><table class="tbl mcards"><thead><tr><th>Kullanıcı adı</th><th>Ad soyad / iletişim</th><th>Durum</th><th>Seviye</th><th class="num">Bakiye</th><th></th></tr></thead><tbody>${U.map(u=>`<tr><td><b>${esc(u.name)}</b> ${u.verified?'<span class="vchk">✔</span>':''} ${!u.staff&&!u.admin?(tcOk(u)?'<span class="chip ok" title="TC kimlik doğrulandı">TC ✔</span>':'<span class="chip warn" title="Kimlik doğrulanmadı, para çekemez">TC yok</span>'):''} ${u.staff?'<span class="chip">Çalışan</span>':''} ${u.banned?'<span class="pill p-iade">Yasaklı</span>':''}</td><td>${esc(fullName(u))}<div class="muted mono" style="font-size:11.5px">${esc(u.tel||'')} ${esc(u.email||'')}</div></td><td>${seenTxt(u)}</td><td>${vipBadge(u)}</td><td class="num">${TL(avail(u))}<div class="muted" style="font-size:11px">${TL(u.bal)} çekilebilir</div></td><td><button class="btn btn-sm btn-primary" data-act="user-open" data-id="${u.id}">Detay</button></td></tr>`).join('')}</tbody></table></div>`; }
function exDetail(o){
  const U=user(o.u), s=srv(o.server)||{name:'?'}, x=S.exchange.find(e=>e.id===o.ex)||{}; const done=o.status==='tamam'||o.status==='iptal';
  const fills=(o.fills||[]).slice().sort((a,b)=>a.price-b.price); const m=exMatched(o), dlv=o.delivered||0, miss=Math.max(0,o.qty-m), pct=v=>Math.max(0,Math.round(v/o.qty*1000)/10);
  const cost=r2(fills.reduce((t,f)=>t+f.qty*f.price,0)), val=r2(fills.reduce((t,f)=>t+f.qty*(f.sell||f.price),0));
  const book=x.id?exBook(x):[]; const next=fills.find(f=>(f.paidQty||0)<f.qty);
  const bf=S.exFieldsBuy.map(f=>`<span>${esc(f.label)}: <b class="mono">${esc((o.f||{})[f.id]||'—')}</b></span>`).join('');
  return `<div class="panel exd"><div class="panel-h"><h3>Borsa #${o.id} · ${esc(s.name)}</h3><div class="hstack"><span class="pill ${EXP[o.status]}">${EXS[o.status]}</span><button class="btn btn-sm" data-act="ex-open" data-id="">Kapat</button></div></div><div class="panel-b stack">
    <div class="exd-top"><div class="exd-buyer"><span class="eyebrow">Alıcı</span><b class="big">${esc(U.name)}</b><span>${esc(fullName(U))} · <span class="mono">${esc(U.tel||'')}</span></span>${bf}<span>Teslim yeri: <b>${esc(o.place||S.set.exPlace)}</b></span><span class="muted">Sipariş: ${dtstr(o.t)}${o.staff?' · üstlenen: '+esc(user(o.staff).name):''}</span></div>
      <div class="exd-sum"><div><span>Sipariş</span><b>${NUM(o.qty)} adet</b></div><div><span>Alıcının ödediği</span><b>${TL(o.total)}</b><small class="muted">${TL(o.price)} / adet</small></div><div><span>Satıcılara ödenecek</span><b>${TL(cost)}</b></div><div><span>Kârınız</span><b class="pos">${TL(r2(val-cost))}</b></div>${o.reserve&&!done?`<div><span>Eksik için bloke</span><b>${TL(o.reserve)}</b></div>`:''}</div></div>
    <div class="exprog"><div class="exbar" role="img" aria-label="${dlv} teslim edildi, ${m-dlv} eşleşti, ${miss} eşleşmedi"><i class="dl" style="width:${pct(dlv)}%"></i><i class="mt" style="width:${pct(m-dlv)}%"></i></div><div class="leg"><span><i class="dl"></i>Teslim edildi: <b>${dlv}</b></span><span><i class="mt"></i>Eşleşti, teslim bekliyor: <b>${m-dlv}</b></span><span><i class="ms"></i>Eşleşmedi: <b>${miss}</b></span></div></div>

    <div class="exstep ${m>=o.qty&&dlv>=o.qty?'done':''}"><div class="exstep-h"><i>1</i><div><b>Satış emri eşle ve yangı al</b><span>Aşağıdaki listeden “Eşle” ile siparişi bir satış emrine bağlayın. Eşlenenler fiyata göre sıralıdır: önce en ucuz satıcıdan alın. Teslim ettiğiniz adet kadar, bu sırayla satıcılara otomatik ödeme yapılır.</span></div>${fills.length&&!done?`<div class="hstack" style="flex-wrap:nowrap">${fills.some(f=>(f.paidQty||0)<f.qty)?`<button class="btn btn-sm btn-bad" data-act="ex-unpair-all" data-id="${o.id}">Tüm eşlemeleri sil</button>`:''}<button class="btn btn-sm" data-act="reveal">${ui.reveal?'Şifreleri gizle':'Şifreleri göster'}</button></div>`:''}</div><div class="exstep-b">
      ${fills.length?`<div class="tbl-w"><table class="tbl"><thead><tr><th>Sıra</th><th>Satıcı</th><th class="num">Birim fiyat</th><th class="num">Adet</th><th class="num">Satıcıya</th><th>Durum</th><th></th></tr></thead><tbody>${fills.map((f,i)=>{ const of=S.exOffers.find(z=>z.id===f.of)||{f:{}}; const SU=user(f.u); const paid=f.paidQty||0; const isN=!done&&f===next;
        return `<tr class="${isN?'nextrow':''}"><td class="mono"><b>${i+1}</b></td><td><b>${esc(SU.name)}</b> · ${esc(fullName(SU))}<div class="muted" style="font-size:11.5px">emir #${f.of} · ${esc(SU.tel||'')}</div></td><td class="num"><b>${TL(f.price)}</b></td><td class="num">${NUM(f.qty)}</td><td class="num">${TL(f.qty*f.price)}</td><td>${paid>=f.qty?'<span class="chip ok">Alındı · ödendi</span>':paid?`<span class="chip">${paid}/${f.qty} alındı</span>`:isN?'<span class="chip warn">Sıradaki</span>':'<span class="chip">Bekliyor</span>'}</td><td>${!done&&paid<f.qty?`<button class="btn btn-sm btn-bad" data-act="ex-unpair" data-id="${o.id}" data-of="${f.of}" title="Teslim alınmamış ${f.qty-paid} adet satış emrine geri döner">Eşlemeyi sil</button>`:''}</td></tr>
        ${!done&&paid<f.qty?`<tr class="credrow"><td></td><td colspan="6"><div class="credbox">${S.exFields.map(fd=>{const v=(of.f||{})[fd.id]; const hide=fd.secret&&!ui.reveal; return `<div><span class="muted">${esc(fd.label)}</span><b class="mono">${v?(hide?'••••••':esc(v)):'—'}</b></div>`}).join('')}</div></td></tr>`:''}`}).join('')}</tbody></table></div>`:'<div class="muted" style="font-size:13px">Bu siparişe henüz satış emri eşlenmedi. Aşağıdaki listeden eşleyin.</div>'}
      ${done?'':`<div class="pairbox"><div class="pairbox-h"><b>${miss>0?miss+' adet eşlenecek (Manuel Eşleme Havuzu)':'Sipariş eşlendi (Dilerseniz manuel ekleme/değiştirme yapabilirsiniz)'}</b><span class="muted">${esc(s.name)} satış emirleri havuzu · en ucuz üstte · alıcı ${TL(o.price)} / adet ödedi</span></div>
        ${book.length?`<div class="tbl-w"><table class="tbl"><thead><tr><th>Sıra</th><th>Satıcı</th><th class="num">Birim fiyat</th><th class="num">Adet başı kâr</th><th class="num">Emirdeki adet</th><th>Eşlenecek</th><th></th></tr></thead><tbody>${book.map((of,i)=>{ const SU=user(of.u); const pr=r2(o.price-of.price); const dq=Math.min(miss>0?miss:of.left,of.left); return `<tr class="${i===0?'nextrow':''}"><td class="mono"><b>${i+1}</b>${i===0?' <span class="chip ok">en ucuz</span>':''}</td><td><b>${esc(SU.name)}</b><div class="muted" style="font-size:11.5px">emir #${of.id} · ${ago(of.t)}</div></td><td class="num"><b>${TL(of.price)}</b></td><td class="num ${pr<0?'neg':'pos'}">${TL(pr)}</td><td class="num">${NUM(of.left)}</td><td><input class="inp mono" type="number" min="1" max="${of.left}" value="${dq||1}" id="pq_${of.id}" style="width:90px" aria-label="Eşlenecek adet"></td><td><button class="btn btn-primary btn-sm" data-act="ex-pair" data-id="${o.id}" data-of="${of.id}">Eşle</button></td></tr>`}).join('')}</tbody></table></div>`:'<div class="muted" style="font-size:13px;padding:6px 2px">Bu serverda şu an satışta emir yok. Yeni satış emri gelince burada fiyat sırasıyla listelenir.</div>'}</div>`}
    </div></div>
    ${done?`<div class="note note-info">${o.status==='tamam'?'İşlem tamamlandı. Satıcılara ödeme yapıldı, gizli hesap bilgileri silindi.':'Sipariş iptal edildi; teslim edilmeyen kısım alıcıya iade edildi ve emirler geri açıldı.'}</div>`:`
    <div class="exstep"><div class="exstep-h"><i>2</i><div><b>Alıcıyı çağır</b><span>Yangı aldıktan sonra alıcıya bildirim ve SMS gönderin; “Geldim, hazırım” dediğinde haber gelir.</span></div>${o.called?(o.ready>o.called?'<span class="chip ok">Alıcı hazır · '+ago(o.ready)+'</span>':'<span class="chip warn">Çağrıldı · '+ago(o.called)+'</span>'):''}</div>
      <form class="exstep-b" data-form="excall" data-id="${o.id}"><div class="hstack" style="flex-wrap:nowrap;align-items:end"><div class="fld" style="flex:1;min-width:0"><label for="excall_msg">Mesaj</label><input class="inp" id="excall_msg" value="${esc(callMsg(o))}"></div><button class="btn btn-primary btn-sm" style="margin-bottom:2px">Çağır</button></div></form></div>
    <div class="exstep"><div class="exstep-h"><i>3</i><div><b>Teslim et ve kaydet</b><span>Alıcıya verdiğiniz toplam adedi yazın. Durum kendiliğinden değişir: hepsi verildiyse Tamamlandı, bir kısmıysa Kısmen teslim edildi.</span></div></div>
      <form class="exstep-b" data-form="exst" data-id="${o.id}"><div class="hstack" style="align-items:end"><div class="fld"><label for="exdq">Toplam teslim edilen</label><input class="inp mono" id="exdq" type="number" min="${dlv}" max="${o.qty}" value="${dlv}" style="width:130px"></div><span class="mono" style="padding-bottom:10px">/ ${NUM(o.qty)} adet</span>
        <div class="qbtns" style="padding-bottom:2px">${m>dlv?`<button type="button" class="btn btn-sm" data-act="exdq-fill" data-v="${m}">Eşleşenin tamamı (${m})</button>`:''}${next&&m>dlv?`<button type="button" class="btn btn-sm" data-act="exdq-fill" data-v="${Math.min(m,dlv+(next.qty-(next.paidQty||0)))}">+ Sıradaki satıcı (${next.qty-(next.paidQty||0)})</button>`:''}</div>
        <button class="btn btn-ok" style="margin-bottom:2px">Teslimatı kaydet</button></div></form></div>
    <div class="hstack" style="justify-content:space-between"><form class="hstack" data-form="exinfo" data-id="${o.id}" style="flex:1;min-width:260px;flex-wrap:nowrap"><input class="inp" id="exinfo_msg" placeholder="Alıcıdan bilgi iste: ör. karakter bulunamadı" style="flex:1;min-width:0"><button class="btn btn-sm">Gönder</button></form><div class="hstack">${o.staff?'':`<button class="btn btn-sm" data-act="ex-claim" data-id="${o.id}">İşlemi üstlen</button>`}<button class="btn btn-sm btn-bad" data-act="ex-cancel" data-id="${o.id}">${dlv?'Kalanı iptal et ve iade':'İptal ve iade'}</button></div></div>`}
    <details class="exlog"><summary>İşlem geçmişi (${o.log.length})</summary><div class="feed" style="margin-top:8px">${o.log.slice().reverse().map(e=>`<div><span>${esc(e.x)}</span><time>${dtstr(e.t)}</time></div>`).join('')}</div></details>
  </div></div>`;
}
